"""Bounded subprocess entrypoint; input paths are generated by the server only."""
import argparse,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.architectural_observations import analyze

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--directory',required=True);p.add_argument('--geometry',action='store_true');p.add_argument('--spatial',action='store_true');p.add_argument('--reference',action='store_true');p.add_argument('--target',action='store_true');a=p.parse_args();folder=Path(a.directory)
    binding=json.loads((folder/'binding.json').read_text())
    if a.target:
        from backend.target_pipeline import analyze_target
        result=analyze_target((folder/'input.pdf').read_bytes(),(folder/'native.png').read_bytes(),binding)
    elif a.reference:
        from backend.reference_pipeline import analyze_reference
        result=analyze_reference((folder/'input.pdf').read_bytes(),(folder/'native.png').read_bytes(),binding)
    elif a.spatial:
        from backend.architectural_spatial import analyze_spatial
        result=analyze_spatial((folder/'input.pdf').read_bytes(),(folder/'native.png').read_bytes(),binding,json.loads((folder/'parent.json').read_text()))
    elif a.geometry:
        from backend.architectural_geometry import analyze_geometry
        result=analyze_geometry((folder/'input.pdf').read_bytes(),(folder/'native.png').read_bytes(),binding,json.loads((folder/'parent.json').read_text()))
    else:result=analyze((folder/'input.pdf').read_bytes(),(folder/'native.png').read_bytes(),binding)
    (folder/'bundle.json').write_text(json.dumps(result,ensure_ascii=False,allow_nan=False,separators=(',',':')))
